'use strict';
const http=require('node:http');const{URL}=require('node:url');const{WorkflowSchemaService,FAMILY,versionsFor,getSchema}=require('./service');const{JobQueue}=require('../persistence/job-queue');const{authenticate,hasRole}=require('../security/http-security');
function supportedVersions(family){const raw=process.env[`FORGE_SCHEMA_${family.replace(/-/g,'_').toUpperCase()}_VERSIONS`];return raw?raw.split(',').map(Number).filter(v=>Number.isInteger(v)&&v>0):versionsFor(family).map(x=>x.version)}
function json(res,status,body){if(res.headersSent)return;res.setHeader('content-type','application/json; charset=utf-8');res.setHeader('cache-control','no-store');res.writeHead(status);res.end(JSON.stringify(body))}
async function readBody(req){const chunks=[];let size=0;for await(const chunk of req){size+=chunk.length;if(size>512*1024)throw Object.assign(new Error('Request body exceeds limit'),{statusCode:413,code:'PAYLOAD_TOO_LARGE'});chunks.push(chunk)}if(!chunks.length)return{};try{return JSON.parse(Buffer.concat(chunks).toString('utf8'))}catch{throw Object.assign(new Error('Malformed JSON'),{statusCode:400,code:'VALIDATION_ERROR'})}}
function installJobQueueGuards(){if(JobQueue.prototype.__forgeWorkflowSchemaGuards)return;const enqueue=JobQueue.prototype.enqueue,claim=JobQueue.prototype.claim,claimSpecific=JobQueue.prototype.claimSpecific;JobQueue.prototype.enqueue=async function(args={}){const family=args.schemaFamily||FAMILY.JOB,version=Number(args.schemaVersion||1),service=new WorkflowSchemaService({pool:this.pool});const s=getSchema(family,version);if(!s)throw Object.assign(new Error('Unknown job schema'),{code:'UNKNOWN_SCHEMA_VERSION'});const p={...(args.payload||{})};if(!p.stage)p.stage=args.kind;if(!p.payload)p.payload=args.payload||{};await service.ensureRegistered({family,version});await service.assertCompatible({family,version,document:p});const row=await enqueue.call(this,args);if(!row)return row;return(await this.pool.query('UPDATE forge_jobs SET schema_family=$1,schema_version=$2,schema_hash=$3 WHERE id=$4 RETURNING *',[family,version,s.canonicalHash,row.id])).rows[0]||row};async function guard(q,job,workerId){if(!job)return null;const family=job.schema_family||FAMILY.JOB,version=Number(job.schema_version||1),service=new WorkflowSchemaService({pool:q.pool}),s=getSchema(family,version);try{await service.ensureRegistered({family,version});if(!s||job.schema_hash!==s.canonicalHash)throw Object.assign(new Error('Persisted job schema hash mismatch'),{code:'SCHEMA_HASH_MISMATCH'});const p={...(job.payload||{})};p.stage=p.stage||job.kind;p.payload=p.payload||job.payload||{};await service.assertCompatible({family,version,document:p,workerSupportedVersions:supportedVersions(family)});return job}catch(error){await q.pool.query(`UPDATE forge_jobs SET status='QUEUED',worker_id=NULL,leased_until=NULL,available_at=now(),updated_at=now(),error=$1::jsonb WHERE id=$2 AND status='RUNNING'`,[JSON.stringify({code:error.code||'SCHEMA_COMPATIBILITY_BLOCKED',message:error.message,details:error.details||null}),job.id]);if(error.code==='WORKER_SCHEMA_UNSUPPORTED')return null;throw error}}JobQueue.prototype.claim=async function(o){return guard(this,await claim.call(this,o),o?.workerId)};JobQueue.prototype.claimSpecific=async function(id,workerId,now){return guard(this,await claimSpecific.call(this,id,workerId,now),workerId)};JobQueue.prototype.__forgeWorkflowSchemaGuards=true}
function installOperatorApi({pool=null,authSecret=process.env.FORGE_AUTH_SIGNING_SECRET||null,apiToken=process.env.API_BEARER_TOKEN||null,staticActor=process.env.FORGE_STATIC_ACTOR_ID||null,staticTenant=process.env.FORGE_STATIC_TENANT_ID||null}={}){if(http.Server.prototype.__forgeWorkflowSchemaOperatorApi)return;http.Server.prototype.__forgeWorkflowSchemaOperatorApi=true;let db=pool;async function getDb(){if(db)return db;if(!process.env.DATABASE_URL)return null;const{Pool}=require('pg');db=new Pool({connectionString:process.env.DATABASE_URL,max:5,idleTimeoutMillis:30000,connectionTimeoutMillis:5000});return db}const emit=http.Server.prototype.emit;http.Server.prototype.emit=function(event,req,res){if(event!=='request')return emit.apply(this,arguments);const u=new URL(req.url||'/','http://localhost');if(!u.pathname.startsWith('/v1/operator/workflow-schemas'))return emit.apply(this,arguments);void handle(req,res,u).catch(e=>json(res,e.statusCode||500,{error:{code:e.code||'INTERNAL_ERROR',message:e.message,details:e.details}}));return true};async function handle(req,res,u){const auth=authenticate(req,{apiToken,authSecret,staticActor,staticTenant});if(!auth)return json(res,401,{error:{code:'UNAUTHORIZED'}});if(!hasRole(auth,'OWNER'))return json(res,403,{error:{code:'FORBIDDEN'}});const p=await getDb();if(!p)return json(res,503,{error:{code:'PERSISTENCE_UNAVAILABLE'}});const service=new WorkflowSchemaService({pool:p});if(req.method==='GET'&&u.pathname==='/v1/operator/workflow-schemas')return json(res,200,{items:await service.inventory({family:u.searchParams.get('family')||null})});if(req.method==='GET'&&u.pathname==='/v1/operator/workflow-schemas/compatibility')return json(res,200,await service.compatibility({family:u.searchParams.get('family'),fromVersion:Number(u.searchParams.get('fromVersion')),toVersion:Number(u.searchParams.get('toVersion'))}));if(req.method==='POST'&&u.pathname==='/v1/operator/workflow-schemas/migrations/dry-run'){const b=await readBody(req);return json(res,200,await service.recordMigration({...b,dryRun:true,actor:auth.actor}))}if(req.method==='POST'&&u.pathname==='/v1/operator/workflow-schemas/migrations'){const b=await readBody(req);return json(res,201,await service.recordMigration({...b,dryRun:false,actor:auth.actor}))}const m=/^\/v1\/operator\/workflow-schemas\/migrations\/([^/]+)\/(rollout|rollback)$/.exec(u.pathname);if(m&&req.method==='POST'){const b=await readBody(req);if(m[2]==='rollout')return json(res,200,await service.rollout({migrationId:m[1],actor:auth.actor,dryRun:Boolean(b.dryRun)}));return json(res,200,await service.rollback({migrationId:m[1],actor:auth.actor,reason:b.reason||''}))}return json(res,404,{error:{code:'NOT_FOUND'}})}}
installJobQueueGuards();installOperatorApi();module.exports={installJobQueueGuards,installOperatorApi,supportedVersions};